class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        # Initialize distances: dist[i] = distance from city 0 to city i
        dist = [i for i in range(n)]

        result = []

        for u, v in queries:
            # Update distances for all cities from v onwards
            for w in range(v, n):
                new_dist = dist[u] + 1 + (w - v)
                if new_dist < dist[w]:
                    dist[w] = new_dist

            result.append(dist[n-1])

        return result

class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        # Build the graph with initial edges (i -> i+1 for all i < n-1)
        graph = [[] for _ in range(n)]
        for i in range(n - 1):
            graph[i].append(i + 1)

        result = []

        for u, v in queries:
            # Add the new edge u -> v
            graph[u].append(v)

            # Use Dijkstra's algorithm to find shortest path from 0 to n-1
            # Distance array: dist[i] = shortest distance from 0 to i
            dist = [float('inf')] * n
            dist[0] = 0

            # Priority queue: (distance, city)
            import heapq
            pq = [(0, 0)]

            while pq:
                d, city = heapq.heappop(pq)
                if d > dist[city]:
                    continue
                if city == n - 1:
                    break

                for neighbor in graph[city]:
                    new_dist = d + 1
                    if new_dist < dist[neighbor]:
                        dist[neighbor] = new_dist
                        heapq.heappush(pq, (new_dist, neighbor))

            result.append(dist[n - 1])

        return result

class Solution:
    def numberOfAlternatingGroups(self, colors: List[int], queries: List[List[int]]) -> List[int]:
        n = len(colors)
        result = []

        for query in queries:
            if query[0] == 2:  # update query
                idx, color = query[1], query[2]
                colors[idx] = color
            else:  # count query
                size = query[1]
                count = 0

                # For size 1, there's always one alternating group (single tile)
                if size == 1:
                    count = n
                elif size == 2:
                    # For size 2, we need adjacent tiles to have different colors
                    count = 0
                    for i in range(n):
                        if colors[i] != colors[(i + 1) % n]:
                            count += 1
                else:
                    # For size >= 3, we need a strictly alternating pattern
                    # Check each starting position
                    for start in range(n):
                        valid = True

                        # Check all adjacent pairs in the group
                        for j in range(size - 1):
                            pos1 = (start + j) % n
                            pos2 = (start + j + 1) % n
                            if colors[pos1] == colors[pos2]:
                                valid = False
                                break

                        if valid:
                            # Check the circular connection between last and first
                            pos1 = (start + size - 1) % n
                            pos2 = start
                            if colors[pos1] != colors[pos2]:
                                count += 1

                result.append(count)

        return result

class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at position 0 (top-left corner)
        row, col = 0, 0

        # Process each command
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1

        # Convert final row and column to grid position
        return row * n + col

class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        # Count balls by player and color
        player_color_count = {}

        for player, color in pick:
            if player not in player_color_count:
                player_color_count[player] = {}
            player_color_count[player][color] = player_color_count[player].get(color, 0) + 1

        # Count winning players
        winning_count = 0
        for player in range(n):
            if player in player_color_count:
                max_count = max(player_color_count[player].values())
                if max_count >= player + 1:
                    winning_count += 1

        return winning_count

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        def calculate_flips(axis):
            """Calculate minimum flips needed for rows (axis=0) or columns (axis=1)"""
            flips = 0

            if axis == 0:  # Rows
                for i in range(m):
                    # For each row, check symmetric pairs
                    for j in range(n // 2):
                        left = grid[i][j]
                        right = grid[i][n - 1 - j]
                        if left != right:
                            flips += 1
            else:  # Columns
                for j in range(n):
                    # For each column, check symmetric pairs
                    for i in range(m // 2):
                        top = grid[i][j]
                        bottom = grid[m - 1 - i][j]
                        if top != bottom:
                            flips += 1

            return flips

        # Calculate flips for rows and columns
        row_flips = calculate_flips(0)
        col_flips = calculate_flips(1)

        # Return minimum
        return min(row_flips, col_flips)

